type CartBadgeProps = {
  count: number;
  max?: number;
};

const DEFAULT_MAX_COUNT = 99;

export function CartBadge({ count, max = DEFAULT_MAX_COUNT }: CartBadgeProps) {
  if (count <= 0) {
    return null;
  }

  const label = count > max ? `${max}+` : String(count);

  return (
    <span className="cart-badge" data-testid="cart-badge" aria-label={`Items in cart: ${label}`}>
      {label}
    </span>
  );
}

